{"source":"#include <stdio.h>
#include <math.h>
int a,b,l;
double f(double x){return cos(x)*(b*tan(x)+a-l*sin(x));}
int main(int i, char *argv[]){
    double w,S=0,T=acos(0),s,t;
    scanf("%d%d%d",&a,&b,&l);
    if(a>b) a^=b^=a^=b;
    if(l<=b) w=l<=a?l:a;
    else {
        for(i=255;i--;){
            s=(S*2+T)/3,t=(S+T*2)/3;
            if(f(s)>f(t)) S=s; else T=t;
        }
        w=f((S+T)/2);
    }
    printf("%f\n",w);
    return 0;
}"}
